export type PayMethod = (typeof PAY_METHODS)[number];
export declare const PAY_LABEL: Record<PayMethod, string>;
export interface PosTrx {
    net: Rupiah;
    ppn: Rupiah;
    total: Rupiah;
    method: PayMethod;
    status: 'selesai' | 'void';
}
